import React, { useEffect } from 'react';

const Skills = () => {
  const skills = [
    { icon: '☁️', title: 'Cloud', percent: 70 },
    { icon: '🐳', title: 'Containers', percent: 80 },
    { icon: '📜', title: 'IaC', percent: 80 },
    { icon: '⚙️', title: 'CI/CD', percent: 70 },
    { icon: '🐚', title: 'Scripting', percent: 60 },
    { icon: '🗂️', title: 'Version Control', percent: 70 },
    { icon: '🔒', title: 'Security', percent: 60 },
    { icon: '📈', title: 'Monitoring', percent: 80 },
  ];

  useEffect(() => {
    skills.forEach((skill, index) => {
      const circle = document.querySelectorAll('.skill-circle')[index];
      if (circle) {
        const progress = circle.querySelector('.progress');
        const radius = 45;
        const circumference = 2 * Math.PI * radius;
        const offset = circumference - (skill.percent / 100) * circumference;
        progress.style.strokeDasharray = circumference;
        progress.style.strokeDashoffset = circumference;
        setTimeout(() => (progress.style.strokeDashoffset = offset), 500);
      }
    });
  }, []);

  return (
    <section id="skills">
      <h2 className="section-title">My Skills</h2>
      <div className="skills-grid">
        {skills.map((skill, index) => (
          <div key={index} className="skill-card">
            <div className="skill-icon">{skill.icon}</div>
            <h3>{skill.title}</h3>
            <div className="skill-circle" data-percent={skill.percent}>
              <svg width="100" height="100">
                <circle cx="50" cy="50" r="45" stroke="#2b2a26" strokeWidth="10" fill="none" />
                <circle className="progress" cx="50" cy="50" r="45" stroke="#d4a373" strokeWidth="10" fill="none" strokeLinecap="round" />
              </svg>
              <span>{skill.percent}%</span>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
};

export default Skills;
